{
  "per_column": [
    {
      "name": "industry_sector",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "A clean categorical axis derived from the description, directly useful for predicting regional clustering. Values are well-supported readings (23andMe->life_science_health, 5AM->venture_capital_finance)."
    },
    {
      "name": "company_type",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Distinguishes startups, corporations, investors, consulting -- a genuine grouping axis. Samples are sound (Accel->venture_capital_investor, 280 Group->staffing_consulting)."
    },
    {
      "name": "company_maturity",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.5,
      "hallucination_observed": true,
      "rationale": "Useful stage axis, but descriptions rarely state maturity. Labels like 23andMe->'established_public_or_large' and Accel->'early_stage' are inferred from outside knowledge, not the terse description text -- confident specifics the source is silent about."
    },
    {
      "name": "core_tech_domain",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.75,
      "hallucination_observed": true,
      "rationale": "Adds a technology axis distinct from industry_sector. Mostly grounded, but 5AM Ventures->biotech_genomics extends the firm's focus into its own tech domain, a stretch. Large 'other' bucket dilutes leverage somewhat."
    },
    {
      "name": "cloud_infra_signal",
      "analytical_usefulness": 0.5,
      "source_groundedness": 0.55,
      "hallucination_observed": true,
      "rationale": "Reasonable when text mentions cloud, but ~half rows are 'not_present' and Addepar->'cloud_native_primary' is inferred (a 'platform' need not be cloud-native). Weak leverage for regional clustering."
    },
    {
      "name": "market_segment",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.8,
      "hallucination_observed": false,
      "rationale": "B2B/B2C segmentation is a solid grouping axis, and samples are warranted readings of the descriptions (23andMe->consumer_b2c, Addepar->enterprise_b2b)."
    },
    {
      "name": "customer_type",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.65,
      "hallucination_observed": true,
      "rationale": "Useful target-market axis, but heavily skewed to 'technology_companies' and often inferred where text is silent (280 Group->technology_companies is not stated). Partially grounded."
    },
    {
      "name": "delivery_model",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.8,
      "hallucination_observed": false,
      "rationale": "Distinguishes SaaS, hardware, services, funding -- a meaningful axis. Samples align well with text (280 Group->professional_services, 5AM->investment_funding)."
    },
    {
      "name": "hardware_software_signal",
      "analytical_usefulness": 0.55,
      "source_groundedness": 0.65,
      "hallucination_observed": true,
      "rationale": "Partly redundant with delivery_model/core_tech_domain. Values often inferred where text does not specify hardware vs software (23andMe->pure_software, though it ships kits). Moderate leverage."
    }
  ],
  "analytical_usefulness": 0.78,
  "source_groundedness": 0.72,
  "rationale": "The set provides several genuine, distinct categorical axes (industry_sector, company_type, market_segment, delivery_model, core_tech_domain) that give real leverage for modeling regional clusters from descriptions. A few columns overlap or offer weak signal (cloud_infra_signal, hardware_software_signal), and several rely on external-knowledge inference where the terse descriptions are silent (company_maturity most notably, plus some customer_type and cloud values), introducing some ungrounded confident specifics. Overall the columns are useful and largely grounded, with pockets of unwarranted inference."
}
